/**
 * Generate PostalForm firewall config.
 *
 * Data source: https://postalform.com
 *
 * PostalForm authenticates with a Bearer token on
 * `https://api.postalform.com/...`.
 */

import { writeOutput } from "./codegen";

const DOCS_URL = "https://postalform.com";
const PLACEHOLDER_VALUE = "CoffeeSafeLocalCoffeeSafeLocalCoffeeSafe";

function generateTypeScript(): string {
  const lines: string[] = [
    "// Auto-generated from PostalForm API docs.",
    `// Source: ${DOCS_URL}`,
    "// Regenerate: cd turbo && pnpm -F @vm0/firewalls-generator generate:postalform",
    "//",
    "// DO NOT EDIT THIS FILE MANUALLY.",
    "",
    'import type { FirewallConfig } from "../firewall-types";',
    "",
    "export const postalformFirewall = {",
    '  name: "postalform",',
    '  description: "PostalForm API",',
    "  placeholders: {",
    `    POSTALFORM_TOKEN: "${PLACEHOLDER_VALUE}",`,
    "  },",
    "  apis: [",
    "    {",
    '      base: "https://api.postalform.com",',
    "      auth: {",
    "        headers: {",
    '          Authorization: "Bearer ${{ secrets.POSTALFORM_TOKEN }}",',
    "        },",
    "      },",
    "      permissions: [],",
    "    },",
    "  ],",
    "} as const satisfies FirewallConfig;",
    "",
  ];
  return lines.join("\n");
}

export async function generate(): Promise<void> {
  console.error("Generating PostalForm firewall config...");
  const ts = generateTypeScript();
  writeOutput("postalform", ts, import.meta.dirname);
}
